def _ok(r):
    if len(r[2])!=3 or r[1] in r[2] or '（　　　）' not in r[0]: return False
    import re
    return not any(re.search(r' (ない|ます|ある|ところ|ようだ|かねる)$', w) or w in ('ならば ない',) for w in r[2])
